    glossary=[("Program", "A list of instructions a computer can run."), ("Algorithm", "A step-by-step method for solving a problem."), ("Command", "One instruction, like move()."), ("Sequencing", "Running commands in order."), ("Function", "A named group of commands."), ("Define", "Create a function. Does not run it."), ("Call", "Run a function by its name."), ("Decomposition", "Splitting a problem into smaller parts."), ("Abstraction", "Hiding details behind a name."), ("Comment", "A note for people, ignored by the computer."), ("For loop", "Repeats a fixed number of times."), ("While loop", "Repeats while a condition is true."), ("Infinite loop", "A loop that never ends."), ("Condition", "A question with a true or false answer."), ("Selection", "Choosing code with if or if/else."), ("Iteration", "Repeating code."), ("Bug", "A mistake in a program."), ("Syntax error", "Breaks the language's rules."), ("Runtime error", "A crash while running."), ("Logic error", "Runs but gives the wrong result.")],
